    if phase == 'readOnlyRecovery':
        # A dispatch result with no read-only standing is a failed check below, not a crash of the whole checker.
        return _S37_PROJ['readOnlyRecovery'].get(_S37_RO_MAP.get(standing))
    return _S37_PROJ[phase][standing]


